def prepare():
    os.makedirs('www', exist_ok=True)
    shutil.copy('index.html', 'www/index.html')
    Image.open('logo.jpg').convert('RGB').resize((192, 192), Image.LANCZOS).save('www/icon-192.png')

def patch():
    base = 'android/app/src/main'
    for rel, text in FILES.items():
        if rel.startswith('java/'):
            dst = os.path.join(base, 'java/com/sina/planner', rel[5:])
        else:
            dst = os.path.join(base, rel)
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        with open(dst, 'w', encoding='utf-8') as f:
            f.write(text)
    src = Image.open('logo.jpg').convert('RGB')
    lum = src.convert('L').point(lambda v: min(255, int(v * 1.25)))
    for d, s, f in [('mdpi', 48, 108), ('hdpi', 72, 162), ('xhdpi', 96, 216), ('xxhdpi', 144, 324), ('xxxhdpi', 192, 432)]:
        o = os.path.join(base, 'res', 'mipmap-' + d)
        os.makedirs(o, exist_ok=True)
        sq = src.resize((s, s), Image.LANCZOS)
        sq.save(os.path.join(o, 'ic_launcher.png'))
        r = sq.convert('RGBA')
        m = Image.new('L', (s, s), 0)
        ImageDraw.Draw(m).ellipse((0, 0, s - 1, s - 1), fill=255)
        r.putalpha(m)
        r.save(os.path.join(o, 'ic_launcher_round.png'))
        k = int(f * 0.62)
        fg = Image.new('RGBA', (f, f), (0, 0, 0, 0))
        w = Image.new('RGBA', (k, k), (255, 255, 255, 255))
        w.putalpha(lum.resize((k, k), Image.LANCZOS))
        fg.paste(w, ((f - k) // 2, (f - k) // 2), w)
        fg.save(os.path.join(o, 'ic_launcher_foreground.png'))
    p = os.path.join(base, 'AndroidManifest.xml')
    s = open(p, encoding='utf-8').read()
    rcv = """<receiver android:name=".SinaWidget" android:exported="true">
  <intent-filter><action android:name="android.appwidget.action.APPWIDGET_UPDATE"/></intent-filter>
  <meta-data android:name="android.appwidget.provider" android:resource="@xml/sina_widget_info"/>
</receiver>
"""
    s = s.replace('</application>', rcv + """<service android:name=".AlarmService" android:exported="false" android:foregroundServiceType="mediaPlayback"/>
<receiver android:name=".AlarmReceiver" android:exported="false"/>
<receiver android:name=".SinaWidgetFin" android:exported="true"><intent-filter><action android:name="android.appwidget.action.APPWIDGET_UPDATE"/></intent-filter><meta-data android:name="android.appwidget.provider" android:resource="@xml/sina_widget_fin_info"/></receiver>
<receiver android:name=".SinaWidgetText" android:exported="true"><intent-filter><action android:name="android.appwidget.action.APPWIDGET_UPDATE"/></intent-filter><meta-data android:name="android.appwidget.provider" android:resource="@xml/sina_widget_text_info"/></receiver>
<receiver android:name=".BootReceiver" android:exported="true"><intent-filter><action android:name="android.intent.action.BOOT_COMPLETED"/></intent-filter></receiver>
""" + '</application>', 1)
    s = s.replace('</manifest>', '<uses-permission android:name="android.permission.POST_NOTIFICATIONS"/>\n<uses-permission android:name="android.permission.RECEIVE_BOOT_COMPLETED"/>\n<uses-permission android:name="android.permission.USE_BIOMETRIC"/>\n<uses-permission android:name="android.permission.RECORD_AUDIO"/>\n<uses-permission android:name="android.permission.VIBRATE"/>\n<uses-permission android:name="android.permission.REQUEST_IGNORE_BATTERY_OPTIMIZATIONS"/>\n<uses-permission android:name="android.permission.WAKE_LOCK"/>\n<uses-permission android:name="android.permission.FOREGROUND_SERVICE"/>\n<uses-permission android:name="android.permission.FOREGROUND_SERVICE_MEDIA_PLAYBACK"/>\n<uses-permission android:name="android.permission.USE_FULL_SCREEN_INTENT"/>\n<queries><intent><action android:name="android.speech.RecognitionService"/></intent></queries>\n</manifest>', 1)
    open(p, 'w', encoding='utf-8').write(s)
    import base64
    KS = ""
    with open(os.path.join(base, '..', '..', 'sina.keystore'), 'wb') as f:
        f.write(base64.b64decode(KS))
    gp = os.path.join(base, '..', '..', 'build.gradle')
    with open(gp, 'a', encoding='utf-8') as f:
        f.write("""
android {
    signingConfigs {
        debug {
            storeFile file('sina.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
    }
}
""")
    with open(gp, 'a', encoding='utf-8') as f:
        f.write("\ndependencies {\n    implementation 'androidx.biometric:biometric:1.1.0'\n}\n")
    pv = Image.new('RGBA', (720, 300), (0, 0, 0, 0))
    d = ImageDraw.Draw(pv)
    d.rounded_rectangle((0, 0, 719, 299), radius=34, fill=(11, 21, 19, 235))
    d.line((360, 28, 360, 272), fill=(255, 255, 255, 40), width=2)
    d.rounded_rectangle((520, 38, 690, 58), radius=8, fill=(236, 250, 243, 230))
    d.rounded_rectangle((390, 104, 690, 114), radius=5, fill=(255, 255, 255, 45))
    d.rounded_rectangle((540, 104, 690, 114), radius=5, fill=(62, 207, 155, 255))
    for i in range(3):
        d.rounded_rectangle((470, 150 + i * 38, 690, 166 + i * 38), radius=8, fill=(255, 255, 255, 70))
    d.rounded_rectangle((60, 38, 330, 58), radius=8, fill=(236, 250, 243, 230))
    for i, hg in enumerate([30, 52, 22, 64, 40, 58, 70]):
        d.rounded_rectangle((40 + i * 40, 274 - hg, 68 + i * 40, 274), radius=6, fill=(62, 207, 155, 200))
    pd_ = os.path.join(base, 'res', 'drawable-nodpi')
    os.makedirs(pd_, exist_ok=True)
    pv.save(os.path.join(pd_, 'widget_preview.png'))
    print('patched')

if __name__ == '__main__':
    {'prepare': prepare, 'patch': patch}[sys.argv[1]]()
